/**
 * One saved view: a named filter set the user can come back to.
 *
 * `filters` is the client's own filter model, stored verbatim — the server
 * keeps the list without interpreting it, so a view saved by a newer build
 * survives being read by an older one (which simply ignores fields it does
 * not know).
 */
export interface SavedView {
  /** Stable id, generated by the client that created the view. */
  id: string;
  name: string;
  filters: Record<string, unknown>;
  /** Grouping the view was saved with, if any. */
  group_by?: string | null;
  /** RFC3339. */
  created_at: string;
}

export interface UserSettingsResponse {
  theme: string;
  palette: string;
  language: string;
  shortcuts: unknown;
  dashboard_layout?: unknown;
  /** Always an array; `[]` when the user has saved none. */
  saved_views: SavedView[];
  notifications_enabled: boolean;
  email_notifications: boolean;
}

export interface UpdateUserSettingsRequest {
  theme?: string | null;
  palette?: string | null;
  language?: string | null;
  shortcuts?: unknown;
  dashboard_layout?: unknown;
  /**
   * Replaces the whole list. Views are read and written together, so there
   * is no per-view endpoint to keep in sync.
   */
  saved_views?: SavedView[];
  notifications_enabled?: boolean | null;
  email_notifications?: boolean | null;
}

export interface UserProfileResponse {
  id: string;
  email: string;
  display_name: string;
  role: string;
  avatar_url?: string | null;
  last_login_at?: string | null;
  created_at: string;
}

export interface UpdateProfileRequest {
  display_name?: string | null;
}
